pub open spec fn installed_reconcile_model<R, S, K, EReq, EResp>() -> ReconcileModel
    where
        R: Reconciler<S, K, EReq, EResp>,
        K: CustomResourceView,
        S: Marshallable,
        EReq: Marshallable,
        EResp: Marshallable,
{
